using System.Collections.Generic;
using System.Linq;
using HexagonalDdd.Order.Application.Ports;
using HexagonalDdd.Order.Domain.Models;

namespace HexagonalDdd.Ui.Infrastructure
{
    /// <summary>
    /// In-memory persistence adapter. Rows are stored as OrderEntity; the boundary
    /// with the domain uses explicit casts generated by CSteroid inside the Domain project.
    /// </summary>
    public class InMemoryOrderRepository : IOrderRepository
    {
        private readonly Dictionary<int, OrderEntity> _rows = new();
        private int _nextId = 1;

        public void Save(OrderBo order)
        {
            if (order.Id == 0)
            {
                order.Id = _nextId++;
            }

            _rows[order.Id] = (OrderEntity)order;
        }

        public OrderBo? FindById(int id)
        {
            return _rows.TryGetValue(id, out var entity) ? (OrderBo)entity : null;
        }

        public IReadOnlyList<OrderBo> FindAll()
        {
            return _rows.Values.OrderBy(e => e.Id).Select(e => (OrderBo)e).ToList();
        }
    }
}
